const bool Incoming = Filter.bMarketOnly
    ? Receipt.To == Filter.Owner : DeltaKnown && Delta > 0;
const bool Outgoing = Filter.bMarketOnly
    ? Receipt.From == Filter.Owner : DeltaKnown && Delta < 0;
if ((Filter.Direction == ETransactionDirection::Incoming
        && !Incoming) ||
    (Filter.Direction == ETransactionDirection::Outgoing
        && !Outgoing)) continue;
